import { Effect } from "effect"

export interface Receipt {
  readonly id: string
  readonly accountId: string
  readonly totalCents: number
}

export interface ReceiptStoreOptions {
  readonly auditEnabled: boolean
  readonly writeAudit: (message: string) => Effect.Effect<void>
}

export const makeReceiptStore = (options: ReceiptStoreOptions) => {
  const receipts = new Map<string, Receipt>()

  const find = (id: string): Effect.Effect<Receipt | undefined> => {
    if (id.length === 0) {
      return Effect.undefined
    }
    return Effect.sync(() => receipts.get(id))
  }

  const audit = (receipt: Receipt): Effect.Effect<void> => {
    if (!options.auditEnabled) {
      return Effect.void
    }
    return options.writeAudit(`Stored receipt ${receipt.id}`)
  }

  const save = (receipt: Receipt): Effect.Effect<void> =>
    Effect.gen(function*() {
      yield* Effect.sync(() => receipts.set(receipt.id, receipt))
      yield* audit(receipt)
    })

  return { find, save }
}
